"""Reconcile authored business guidance with explicitly inspected repository contracts."""
from pathlib import Path
import argparse,json,hashlib,uuid
root=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--erp-root',type=Path,required=True);erp=p.parse_args().erp_root
catalog=json.loads((root/'lib/faq-catalog.json').read_text(encoding='utf-8'))
# Existing keys, actual source, bounded rule, worked example and applicable real UI context.
specs=[
('sales-general-01','SL-PLAN','src/test/java/Invoice/SalesScenarioTest.java','إيه أثر عرض السعر وأمر البيع والفاتورة على الرصيد؟','في أمثلة النشاط العام، عرض السعر وأمر البيع لا يغيران كمية المخزون، بينما فاتورة البيع تخصم الكمية والمرتجع يضيفها. عدم الخصم وحده لا يثبت وجود حجز مخزني.','لو المخزون 20 وكمية المستند 3: العرض والأمر يتركانه 20، والفاتورة يصبح بعدها 17، والمرتجع يزيد الرصيد بمقدار 3. قارن نفس الصنف والوحدة والمخزن.','erp-sales-order.jpg'),
('sales-general-02','SL-ORDER','src/test/java/Invoice/SalesScenarioTest.java','لو أمر البيع 3 وحدات والمخزون 20، المفروض أشوف كام؟','في مثال النشاط العام الموضح هنا، أمر البيع يترك كمية المخزون دون تغيير. الحجز مفهوم مستقل يحتاج مراجعة مستقلة؛ راجع نوع المستند قبل تفسير الرصيد.','المثال: مخزون 20 وأمر بيع بكمية 3؛ الرصيد المتوقع 20. لا تقارنه بفاتورة بيع محفوظة بكمية 3، لأن أثرها المتوقع مختلف.','erp-sales-order.jpg'),
('sales-general-08','SL-ADVANCE','src/test/java/Invoice/SalesScenarioTest.java','ليه رصيد العميل ممكن يتغير من أمر بيع نقدي رغم ثبات المخزون؟','أمر البيع النقدي قد يتضمن دفعة مقدمة تؤثر في رصيد العميل رغم ثبات كمية المخزون. في الأمثلة الموضحة، أمر البيع الآجل وعرض السعر لا يغيران الرصيد؛ راجع نوع السداد وسند الدفعة.','بدون ضريبة: أمر نقدي بقيمة 300 يتوقع تغير الرصيد الموقع بمقدار -300؛ أمر آجل بنفس القيمة يتوقع صفر تغير. راجع سند الدفعة ونوع السداد، ولا تسجل دفعة ثانية لمجرد ثبات المخزون.','erp-sales-order.jpg'),
('sales-general-05','SL-RETURN','src/test/java/Invoice/LinkedSalesReturnTest.java','لو براجع مرتجع مرتبط، أطابق إيه مع الفاتورة الأصلية؟','المرتجع المرتبط يرجع لفاتورة المصدر وتُراجع كميته في حدود كمية المصدر. المرتجع الحر له مسار منفصل؛ لا تغيّر النوع لمجرد تجاوز قيد المرتجع المرتبط.','طابق رقم فاتورة المصدر والصنف والوحدة والكمية والسعر والضريبة. مثال: مصدر بكمية 3 لا يستخدم كمبرر لمرتجع مرتبط بكمية 4. الحد الفعلي يراجع مع المرتجعات السابقة والحالة الحالية.','erp-sales-form-20261103.png'),
('purchases-general-01','PU-STOCK','src/test/java/Purches/PurchaseScenarioTest.java','مثال بالأرقام: أثر أمر الشراء والفاتورة والمرتجع على المخزن؟','في دورة الشراء الموضحة، أمر الشراء يترك كمية المخزون دون تغيير، وفاتورة الشراء تزيدها ومرتجع المشتريات ينقصها. الدفع للمورد حركة مالية منفصلة عن كمية المخزون.','لو الرصيد 20 والكمية 3: أمر الشراء يترك 20، والفاتورة تزيده إلى 23، والمرتجع ينقص الرصيد الذي سبق تنفيذه بمقدار 3. يجب ثبات المخزن غير المعني.','erp-receipt-required-store.png'),
('purchases-general-07','PU-DISCOUNT','src/test/java/Purches/PurchaseFormActions.java','خصم المشتريات اترفض: أعدّل الإجمالي يدوي ولا أراجع الصلاحية؟','صحة حساب الخصم لا تعني السماح للمستخدم بحفظه. راجع الصلاحية وحد الخصم ورسالة الرفض قبل الحفظ؛ لا تفترض نسبة مسموحة غير ظاهرة ولا تعتبر الرفض دليلًا على نجاح العملية.','راجع رسالة الرفض وحد الخصم إن كان ظاهرًا، ثم اطلب الصلاحية المناسبة. لا تعتبر رفض الخصم حفظًا ناجحًا، ولا تكرر الحفظ قبل التأكد من حالة المستند.','erp-sales-form-20261103.png'),
('inventory-general-01','ST-MOVEMENT','src/test/java/StoreTest/StoreSaveVerification.java','مثال: الإضافة والصرف والتالف بيغيروا الكمية إزاي؟','إذن الإضافة يزيد كمية المخزن، والصرف والتالف ينقصانها في الأمثلة الموضحة. راجع المخزن والصنف والوحدة ونوع الحركة قبل مقارنة الرصيد.','رصيد 20: إضافة 3 تعطي 23، أو صرف 3 يعطي 17، أو تالف 3 يعطي 17. هذه أمثلة مستقلة، وليست ثلاث حركات نُفذت بالتتابع.','erp-receipt-required-store.png'),
('inventory-general-02','ST-TRANSFER','src/test/java/StoreTest/StoreSaveVerification.java','مثال بالأرقام: أراجع طرفي تحويل المخازن إزاي؟','تحويل المخازن ينقص كمية المصدر ويزيد كمية الوجهة. قارن الطرفين بنفس الصنف والوحدة والكمية، ولا تكتفِ بتغير طرف واحد.','مصدر رصيده 20 ووجهة رصيدها 5، وتحويل 3: المتوقع 17 في المصدر و8 في الوجهة. مجموع الاثنين يظل 25 في هذا المثال دون حركات أخرى.','live-warehouses-form.png'),
('inventory-general-06','ST-MANUFACTURE','src/test/java/StoreTest/StoreSaveVerification.java','هل كل تصنيع وحدة منتج بيستهلك وحدتين خام؟','التصنيع يزيد المنتج ويستهلك المدخلات حسب وصفة الصنف المعتمدة. نسبة 2 خام إلى 1 منتج هي مثال لوصفة محددة، وليست قاعدة عامة لكل تصنيع.','لو الوصفة المعتمدة تستهلك 2 خام لإنتاج 1 منتج، فإنتاج 3 يستهلك 6 خام. غيّر الحساب حسب الوصفة والوحدة الفعلية، لا حسب المثال وحده.','erp-receipt-required-store.png'),
('accounting-general-04','GL-INVENTORY','src/main/java/Plugin_ERP/Business/Calculator/InventoryPostingExpectation.java','مثال: إيه قيد التكلفة الإضافي في الجرد المستمر؟','نموذج الترحيل يضيف في الجرد المستمر مدين تكلفة المبيعات ودائن المخزون بقيمة التكلفة. الجرد الدوري لا يضيف هذين السطرين في نفس نموذج البيع. المرتجع يعكس الإشارات.','بيع بضاعة قبل الضريبة 100 وتكلفتها 60 وVAT بقيمة 15، دون إضافية: النموذج يتوقع العميل مدين 115، المبيعات دائن 100، الضريبة دائن 15. المستمر يضيف تكلفة مبيعات مدين 60 ومخزون دائن 60.','erp-journal-report-filters.png'),
('sales-general-09','TAX-POLICY','src/main/java/Plugin_ERP/Business/Calculator/BranchInvoiceCalculator.java','مثال توضيحي: الفرق بين سعر شامل الضريبة وسعر غير شامل؟','لو إعداد الفرع ضريبة قيمة مضافة 15% وسعرًا شاملًا، اقسم السعر بعد الخصم على 1.15 لاستخراج الأساس. السعر غير الشامل تضاف إليه الضريبة؛ لا تستخدم 15% تلقائيًا مع إعداد أو نشاط آخر.','مثال مشروط بسياسة 15%: سعر شامل 115 = أساس 100 وضريبة 15. أساس غير شامل 100 + ضريبة 15 = صافي 115. في ItemBased تُستبعد البنود المعفاة من وعاء الضريبة حسب السياسة.','erp-credit-form-20261103.png'),
('sales-general-06','TAX-ROUND','src/main/java/Plugin_ERP/Business/Calculator/BranchInvoiceCalculator.java','ليه فرق قرش ممكن يظهر رغم إن السعر والكمية صح؟','فرق الإجمالي قد يرتبط بالتقريب على مستوى السطر أو الفاتورة، أو بالاحتفاظ بالدقة الوسيطة حتى الصافي النهائي. طابق طريقة التقريب المطبقة على نفس المستند، بدل خلط نتائج طرق مختلفة.','راجع دقة العملة، وموضع التقريب، والخصم والضريبة وإعداد الفرع. لا تغيّر سعر بند أو تضف خصمًا لتعويض فرق صغير غير مفسر؛ سجّل الأرقام قبل وبعد التقريب.','erp-sales-form-20261103.png'),
('sales-restaurant-04','REST-EXTRA','src/main/java/Plugin_ERP/Business/Calculator/RestaurantAdditionalTaxCalculator.java','مثال المطعم: ليه الإضافية أعلى من نسبة سعر الصنف؟','في المثال المشروط بتفعيل الضريبة الإضافية ومعدل موجب وحد أدنى 25 لكل وحدة، تؤخذ القيمة الأكبر بين نسبة الإضافية من الأساس بعد الخصم والحد الأدنى. طابق إعداد فرع المطعم؛ هذه ليست قاعدة عامة لكل نشاط.','بفرض كمية 3 وسعر قبل VAT قيمته 10 وإضافية 10%: النسبة = 3، والحد الأدنى = 75، فالإضافية المتوقعة 75. مع VAT 15% على الوعاء 105 تكون VAT 15.75 والصافي 120.75.','erp-restaurant-payment-panel.png'),
('sales-restaurant-05','REST-RETURN-ISSUE','docs/testing/KNOWN_BUSINESS_ISSUES.md','مرتجع المطعم طلع إضافية أقل من الأصل: أعدّلها ولا أصعّد الحالة؟','لو إجمالي المرتجع المرتبط في المطعم مختلف، راجع إضافية وضريبة فاتورة المصدر قبل الحفظ. توجد حالة تاريخية محددة على سياسة الصافي NetBased اختلف فيها رد الحد الأدنى للإضافية؛ لا تفترض استمرارها أو انطباقها على نسختك.','لإرجاع وحدة، المتوقع في الحالة الموثقة إضافية 25 وVAT 5.25 وصافي 40.25؛ المرصود تاريخيًا كان إضافية 10 وVAT 3 وصافي 23. لا تحفظ على أساس المثال كحل؛ جهز مرجع المصدر والقيم للدعم. هذه ملاحظة تاريخية محددة لا تعمم على كل نسخة.','erp-restaurant-payment-panel.png'),
('hr-hr-05','HR-PERCENT','src/main/java/Plugin_ERP/Business/HumanResources/HrSalaryExpectation.java','مثال راتب 5000: بند 10% يساوي كام؟','بند النسبة يحسب من الراتب الأساسي الشهري: الأساسي × النسبة ÷ 100. راجع طبيعة البند وهل هو استحقاق أم استقطاع؛ النسبة وحدها لا تحدد اتجاه التأثير.','أساسي 5000 × 10 ÷ 100 = 500.00. المبلغ يضاف إذا كان استحقاقًا ويخصم إذا كان استقطاعًا وفق الحركة المسجلة، وليس لمجرد وجود الاسم.','erp-hr-adjustment-list.png'),
('hr-hr-06','HR-DAYS','src/main/java/Plugin_ERP/Business/HumanResources/HrSalaryExpectation.java','مثال راتب 5000: يومين أو أربع ساعات يتحسبوا إزاي؟','بند الأيام = الأساسي ÷ 30.4167 × الأيام، وبند الساعات = الأساسي ÷ 30.4167 ÷ 8 × الساعات. احتفظ بالدقة الوسيطة ثم قرّب الناتج النهائي لخانتين.','مع أساسي 5000: يوم واحد 164.38، يومان 328.77، أربع ساعات 82.19. لا تستخدم حساب أول راتب جزئي لهذه البنود؛ له قاعدة مستقلة.','erp-hr-adjustment-list.png'),
('hr-hr-07','HR-FIRST','src/main/java/Plugin_ERP/Business/HumanResources/HrSalaryExpectation.java','هل أول راتب جزئي بيتحسب بنفس قسمة بند الأيام؟','نموذج أول راتب جزئي مستقل: اليوم = الأساسي × 12 ÷ 365، ثم يضرب في أيام الاستحقاق الفعلية. الشهر المؤهل كاملًا يرجع الأساسي الكامل. إدخال يوم التعيين أو استبعاده قرار صريح في السياسة.','أساسي 5000 وعشرة أيام مؤهلة: 5000 × 12 ÷ 365 × 10 = 1643.84 بعد التقريب. طابق الشهر الميلادي وتاريخ التعيين وسياسة احتساب يوم التعيين؛ لا تفترض ضمه تلقائيًا.','erp-hr-salary-calculation-form.png'),
('hr-hr-08','HR-ABSENCE','docs/hr/BUSINESS_RULES_AR.md','غياب الموظف ظاهر، ليه مش شرط ألاقي نفس القيمة مخصومة من الراتب؟','لا تعتبر تسجيل الغياب أو الإجازة وحده خصمًا تلقائيًا من الراتب. راجع سياسة المنشأة وحركة الاستقطاع المسجلة وبنود الراتب قبل تفسير الصافي أو إضافة خصم جديد.','طابق الغياب أو الإجازة مع السياسة وحركة الاستقطاع وبنود الراتب. لا تسجل خصمًا ثانيًا قبل التأكد من عدم وجود استقطاع مسجل لنفس الحالة.','erp-hr-vacation-list.png'),
('hr-hr-09','HR-ADVANCE','docs/hr/BUSINESS_RULES_AR.md','سلفة 1200 على 3 أقساط: أراجع الخصم الشهري إزاي؟','السلفة تخصم طبقًا للجدول المسجل لها؛ لا نفترض خصم المبلغ كاملًا في أول شهر. الشاشة تعرض عدد الأقساط وقيمة القسط وتاريخ البداية.','مثال حسابي لثلاثة أقساط متساوية دون رسوم: 1200 ÷ 3 = 400 للقسط. راجع التواريخ والقيم المسجلة، وأي استثناء؛ المثال لا يستبدل الجدول الفعلي.','erp-hr-advance-list.png'),
('sales-cars-01','CAR-IDENTITY','docs/testing/evidence/car-chassis-sales-report-content-qualified-native-2026-11-03.json','في تقرير السيارات، إيه اللي يثبت إن السطر يخص العربية المطلوبة؟','لتحديد العربية الصحيحة، طابق اسم السيارة ورقم الشاسيه واللون والحالة والمخزن والصنف ورقم الفاتورة وتاريخها وسعر البيع. تشابه الاسم وحده لا يكفي لتحديد نفس السيارة.','ابدأ بالشاسيه واللون ورقم المستند، ثم سعر السطر والإجماليات. لو الحالة مستعملة أو فيها مرتجع أو فلاتر متعارضة، جهز تفاصيلها للدعم؛ المقارنة البسيطة لا تحسم هذه الحالات.','erp-car-sales-report-picker.png'),
('reports-general-01','REPORT-FILTER','docs/testing/evidence/item-stagnation-report-content-qualified-native-2026-11-03.json','تقرير الركود اختلف بعد فلتر العميل أو تاريخ النهاية: أراجع إيه؟','اختلاف العميل أو المندوب أو فترة التقرير قد يغير الصفوف الظاهرة في تقرير الركود. اختفاء بيع من النطاق المختار لا يعني حذف مستنده؛ راجع كل فلتر مع نفس الصنف والمخزن.','ابدأ بنفس الصنف والمخزن والفترة، ثم غيّر فلترًا واحدًا. طابق هوية آخر بيع والكمية والقيمة والتاريخ، ولا تفسر اختفاء السطر على أنه حذف للمستند.','erp-item-stagnation-dates.png'),
]
bykey={e['key']:e for e in catalog};rules=[];new=[]
for key,rule,path,title,answer,example,image in specs:
 source=erp/path
 assert source.is_file(),path
 parent=bykey.get(key)
 if parent is None:
  parent=next(e for e in catalog if e['content']['module']=='reports')
 module=parent['content']['module'];activities=parent['content']['activities']
 sha=hashlib.sha256(source.read_bytes()).hexdigest()
 rules.append(dict(id=rule,source=path,sha256=sha,scope='SOURCE_CONTRACT' if path.startswith('src/') else 'HISTORICAL_DOCUMENTED_EVIDENCE',answer=answer,example=example,articleKeys=[key],module=module,activities=activities))
 # Improve the existing question without changing its identity or publishing it.
 if key in bykey and rule!='REPORT-FILTER':
  c=parent['content'];c['summary']=answer;c['steps'][0]['text']=answer;c['steps'][1]['text']=example
  c['reply']=answer+'\n'+example
  c['verificationNote']='SOURCE_REVIEW 2026-11-03; not LIVE. Rule '+rule+'. '+path+' SHA256 '+sha+'. Contract/evidence read against ERP HEAD 75fc13b0a0abe1b4f1d6bd0af541837f08b4f9f9 plus local changes. No current transaction execution.'
 content=dict(title=title,summary=answer,module=module,activities=activities,aliases=[rule,title.replace('إيه','ايه')],kind='شرح مفهوم',scopeNote='شرح القاعدة والمثال حسب عقد المشروع وإعداداته المذكورة؛ لا يعني تنفيذ حركة على حسابك أو اعتماد كل إصدارات البرنامج.',prerequisites=['حدد النشاط وسياسة الفرع ونوع المستند قبل تطبيق المثال.','الأرقام أمثلة توضيحية؛ طابق بيانات مستندك ووحدته ومخزنه أو شهر الراتب.'],steps=[dict(title='راجع القاعدة في سياق الشاشة',text=answer,image=dict(kind='asset',name=image),caption='صورة فعلية من البرنامج لتوضيح سياق الشاشة؛ لا تثبت تنفيذ المثال الحسابي.',focus=None),dict(title='طبّق المثال على نفس الإعدادات',text=example,image=dict(kind='asset',name=image),caption='صورة فعلية مرجعية؛ الأرقام المشروحة مثال مستقل وليست نتيجة محفوظة في الصورة.',focus=None)],outcome='تفسير الأثر المتوقع أو الفرق ومراجعته على نفس السياق؛ لو الأرقام الفعلية تخالفه ارفع الحالة مع مرجع المستند دون تكرار الحركة.',warnings=['لا تعمم نسب الضريبة أو أساليب التقريب أو أمثلة الرواتب خارج الإعدادات المذكورة.','الاختلاف الموثق يصعّد للدعم ولا يعالج بتعديل سعر أو رصيد غير مبرر.'],relatedIds=[parent['id']],reply=answer+'\n'+example,verifiedAt='2026-11-03',verificationNote='SOURCE_REVIEW 2026-11-03; not LIVE. Rule '+rule+'. '+path+' SHA256 '+sha+'. Source contract/historical evidence; image is context only, not calculation execution. ERP HEAD 75fc13b0a0abe1b4f1d6bd0af541837f08b4f9f9 with local changes.')
 new.append(dict(id=str(uuid.uuid5(uuid.NAMESPACE_URL,'plugin-soft-business-v1/'+rule)),key='business-v1-'+rule.lower(),source=path,content=content,screenKeys=parent.get('screenKeys',[])))
known={e['id'] for e in catalog};catalog.extend(e for e in new if e['id'] not in known)
(root/'lib/source-business-rules.json').write_text(json.dumps(rules,ensure_ascii=False,indent=2),encoding='utf-8')
(root/'lib/faq-catalog.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2),encoding='utf-8')
meta=json.loads((root/'lib/catalog-coverage.json').read_text(encoding='utf-8'));meta.update(total=len(catalog),articlesWithImages=sum(any(s['image'] for s in e['content']['steps']) for e in catalog),sourceReviewedBusinessArticles=len(new),sourceReviewedRules=len(rules))
(root/'lib/catalog-coverage.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(dict(catalog=len(catalog),sourceRules=len(rules),newIllustratedConcepts=len(new),enrichedExisting=sum(x[0] in bykey for x in specs),published=0)))
